package com.markethub.catalog.api;
import com.markethub.catalog.repository.ProductRepository; import com.markethub.common.api.ApiResponse; import org.springframework.data.domain.PageRequest; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/vendors/{vendorId}/products") public class ProductController { private final ProductRepository products; public ProductController(ProductRepository products){this.products=products;} @GetMapping public ApiResponse<?> list(@PathVariable UUID vendorId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="20") int size){if(page<0||size<1||size>100)throw new IllegalArgumentException("Invalid pagination");return ApiResponse.ok(products.findByVendorIdAndStatus(vendorId,"ACTIVE",PageRequest.of(page,size)));} }